syntax:
void (*destructor)(void *self); // Function pointer for destructor

// Struct with destructor pointer
struct Class {
    void (*destructor)(void *self);
    // other members
};

// Derived class struct
struct DerivedClass {
    struct Class base;
    // additional members
};

// Destructor invocation sequence
call_destructor(struct Class *obj) {
    if (obj && obj->destructor) {
        obj->destructor(obj);
    }
}

