struct ZooAnimal {
    void (*destroy)(struct ZooAnimal *self);
};
struct Bear {
    struct ZooAnimal base;
    // Bear-specific members
};
struct Panda {
    struct Bear base;
    // Panda-specific members
};
void destroy_Panda(struct ZooAnimal *self) {
    // Cast to Panda if needed and cleanup resources
    // Call base destructors in reverse order
    struct Panda *panda = (struct Panda *)self;
    // Cleanup Panda-specific resources
    // Then call Bear destructor
    destroy_Bear(&panda->base);
}
void destroy_Bear(struct ZooAnimal *self) {
    struct Bear *bear = (struct Bear *)self;
    // Cleanup Bear-specific resources
    // Then call ZooAnimal destructor
    destroy_ZooAnimal(self);
}
